from pathlib import Path
import subprocess

ROOT = Path.cwd()
head = subprocess.check_output(['git','rev-parse','--short','HEAD'], text=True).strip()
if not head.startswith('3d381f7'):
    raise SystemExit(f'Expected HEAD 3d381f7, found {head}. Stop and have ChatGPT re-inspect.')

def read(rel):
    return (ROOT / rel).read_text(encoding='utf-8')

def write(rel, content):
    p = ROOT / rel
    p.parent.mkdir(parents=True, exist_ok=True)
    p.write_text(content, encoding='utf-8')

def repl(text, old, new, label):
    count = text.count(old)
    if count != 1:
        raise SystemExit(f'{label}: expected 1 match, found {count}')
    return text.replace(old, new, 1)

for rel in [
    'lib/cosmetics/get-equipped-cosmetic.ts',
    'components/cosmetics/cosmetic-frame-overlay.tsx',
    'app/api/cosmetics/chat/route.ts',
]:
    if (ROOT / rel).exists():
        raise SystemExit(f'{rel} already exists; stop.')

write('lib/cosmetics/get-equipped-cosmetic.ts', 'import "server-only";\n\nimport {\n  createAdminClient,\n} from "@/lib/supabase/admin";\n\nexport type EquippedCosmetic = {\n  id: string;\n  name: string;\n  assetUrl: string;\n};\n\nexport async function getEquippedCosmetic(\n  characterId: string,\n  category:\n    | "sheet_frame"\n    | "chat_frame",\n): Promise<EquippedCosmetic | null> {\n  const admin =\n    createAdminClient();\n\n  const {\n    data: preference,\n    error: preferenceError,\n  } = await admin\n    .from(\n      "character_cosmetic_preferences",\n    )\n    .select(\n      "equipped_sheet_frame_id, equipped_chat_frame_id",\n    )\n    .eq(\n      "character_id",\n      characterId,\n    )\n    .maybeSingle();\n\n  if (preferenceError) {\n    throw new Error(\n      `Unable to load equipped cosmetic: ${preferenceError.message}`,\n    );\n  }\n\n  const cosmeticId =\n    category ===\n    "sheet_frame"\n      ? preference\n          ?.equipped_sheet_frame_id\n      : preference\n          ?.equipped_chat_frame_id;\n\n  if (!cosmeticId) {\n    return null;\n  }\n\n  const [\n    cosmeticResult,\n    entitlementResult,\n  ] = await Promise.all([\n    admin\n      .from(\n        "cosmetic_items",\n      )\n      .select(\n        "id, name, category, asset_url, is_active",\n      )\n      .eq(\n        "id",\n        cosmeticId,\n      )\n      .maybeSingle(),\n\n    admin\n      .from(\n        "character_cosmetic_entitlements",\n      )\n      .select("enabled")\n      .eq(\n        "character_id",\n        characterId,\n      )\n      .eq(\n        "cosmetic_item_id",\n        cosmeticId,\n      )\n      .maybeSingle(),\n  ]);\n\n  if (\n    cosmeticResult.error ||\n    entitlementResult.error\n  ) {\n    throw new Error(\n      `Unable to validate equipped cosmetic: ${\n        cosmeticResult.error\n          ?.message ??\n        entitlementResult.error\n          ?.message ??\n        "Unknown error"\n      }`,\n    );\n  }\n\n  if (\n    !cosmeticResult.data ||\n    cosmeticResult.data\n      .is_active !== true ||\n    cosmeticResult.data\n      .category !== category ||\n    !cosmeticResult.data\n      .asset_url ||\n    entitlementResult.data\n      ?.enabled !== true\n  ) {\n    return null;\n  }\n\n  return {\n    id:\n      cosmeticResult.data.id,\n    name:\n      cosmeticResult.data.name,\n    assetUrl:\n      cosmeticResult.data\n        .asset_url,\n  };\n}\n')
write('components/cosmetics/cosmetic-frame-overlay.tsx', 'type CosmeticFrameOverlayProps = {\n  assetUrl:\n    | string\n    | null\n    | undefined;\n  layer?:\n    | "front"\n    | "background";\n};\n\nexport function CosmeticFrameOverlay({\n  assetUrl,\n  layer = "front",\n}: CosmeticFrameOverlayProps) {\n  if (!assetUrl) {\n    return null;\n  }\n\n  return (\n    // eslint-disable-next-line @next/next/no-img-element\n    <img\n      src={assetUrl}\n      alt=""\n      aria-hidden="true"\n      draggable={false}\n      className={[\n        "pointer-events-none absolute inset-0 h-full w-full select-none object-fill",\n        layer ===\n        "front"\n          ? "z-20"\n          : "z-[1]",\n      ].join(" ")}\n    />\n  );\n}\n')
write('app/api/cosmetics/chat/route.ts', 'import {\n  NextRequest,\n  NextResponse,\n} from "next/server";\n\nimport {\n  createAdminClient,\n} from "@/lib/supabase/admin";\nimport {\n  createClient,\n} from "@/lib/supabase/server";\n\nexport const dynamic =\n  "force-dynamic";\n\nconst UUID =\n  /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;\n\nexport async function GET(\n  request: NextRequest,\n) {\n  const supabase =\n    await createClient();\n\n  const {\n    data: { user },\n  } =\n    await supabase.auth.getUser();\n\n  if (!user) {\n    return NextResponse.json(\n      {\n        error:\n          "Not authorised.",\n      },\n      {\n        status: 401,\n      },\n    );\n  }\n\n  const rawIds =\n    request.nextUrl.searchParams\n      .get("ids") ??\n    "";\n\n  const characterIds =\n    Array.from(\n      new Set(\n        rawIds\n          .split(",")\n          .map(\n            (value) =>\n              value.trim(),\n          )\n          .filter(\n            (value) =>\n              UUID.test(\n                value,\n              ),\n          ),\n      ),\n    ).slice(0, 100);\n\n  if (\n    characterIds.length ===\n    0\n  ) {\n    return NextResponse.json({\n      frames: {},\n    });\n  }\n\n  const admin =\n    createAdminClient();\n\n  const {\n    data: preferences,\n    error: preferenceError,\n  } = await admin\n    .from(\n      "character_cosmetic_preferences",\n    )\n    .select(\n      "character_id, equipped_chat_frame_id",\n    )\n    .in(\n      "character_id",\n      characterIds,\n    )\n    .not(\n      "equipped_chat_frame_id",\n      "is",\n      null,\n    );\n\n  if (preferenceError) {\n    return NextResponse.json(\n      {\n        error:\n          preferenceError.message,\n      },\n      {\n        status: 500,\n      },\n    );\n  }\n\n  const cosmeticIds =\n    Array.from(\n      new Set(\n        (\n          preferences ?? []\n        )\n          .map(\n            (entry) =>\n              entry\n                .equipped_chat_frame_id,\n          )\n          .filter(Boolean),\n      ),\n    );\n\n  if (\n    cosmeticIds.length === 0\n  ) {\n    return NextResponse.json({\n      frames: {},\n    });\n  }\n\n  const [\n    cosmeticsResult,\n    entitlementsResult,\n  ] =\n    await Promise.all([\n      admin\n        .from(\n          "cosmetic_items",\n        )\n        .select(\n          "id, asset_url, category, is_active",\n        )\n        .in(\n          "id",\n          cosmeticIds,\n        )\n        .eq(\n          "category",\n          "chat_frame",\n        )\n        .eq(\n          "is_active",\n          true,\n        ),\n\n      admin\n        .from(\n          "character_cosmetic_entitlements",\n        )\n        .select(\n          "character_id, cosmetic_item_id, enabled",\n        )\n        .in(\n          "character_id",\n          characterIds,\n        )\n        .in(\n          "cosmetic_item_id",\n          cosmeticIds,\n        )\n        .eq(\n          "enabled",\n          true,\n        ),\n    ]);\n\n  const firstError =\n    cosmeticsResult.error ??\n    entitlementsResult.error;\n\n  if (firstError) {\n    return NextResponse.json(\n      {\n        error:\n          firstError.message,\n      },\n      {\n        status: 500,\n      },\n    );\n  }\n\n  const cosmetics =\n    new Map(\n      (\n        cosmeticsResult.data ??\n        []\n      )\n        .filter(\n          (entry) =>\n            Boolean(\n              entry.asset_url,\n            ),\n        )\n        .map(\n          (entry) => [\n            entry.id,\n            entry.asset_url,\n          ],\n        ),\n    );\n\n  const enabledPairs =\n    new Set(\n      (\n        entitlementsResult.data ??\n        []\n      ).map(\n        (entry) =>\n          `${entry.character_id}:${entry.cosmetic_item_id}`,\n      ),\n    );\n\n  const frames:\n    Record<\n      string,\n      string\n    > = {};\n\n  for (\n    const preference of\n      preferences ?? []\n  ) {\n    const cosmeticId =\n      preference\n        .equipped_chat_frame_id;\n\n    if (\n      !cosmeticId ||\n      !enabledPairs.has(\n        `${preference.character_id}:${cosmeticId}`,\n      )\n    ) {\n      continue;\n    }\n\n    const assetUrl =\n      cosmetics.get(\n        cosmeticId,\n      );\n\n    if (assetUrl) {\n      frames[\n        preference.character_id\n      ] = assetUrl;\n    }\n  }\n\n  return NextResponse.json({\n    frames,\n  });\n}\n')

